WITH with_last AS (SELECT s.*, latest.product_stock_qty, latest.price FROM suppliers s LEFT JOIN LATERAL (SELECT c.stock_qty AS product_stock_qty, c.price FROM products c WHERE c.supplier_id = s.id ORDER BY c.stock_qty DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, supplier_name, country, city, rating, product_stock_qty, CASE WHEN country RLIKE '^(US|JP)$' THEN 'CORE' WHEN country RLIKE '^(TH|SG)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS country_zone FROM with_last ORDER BY id DESC
